insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"mayadialougtobe","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q01_new_quest_step_01_3","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q02_new_quest_start","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q02_new_quest_step_01","speaker_external_id":"Benny the Builder","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q02_new_quest_step_04","speaker_external_id":"Benny the Builder","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q02_new_quest_step_08","speaker_external_id":"Benny the Builder","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q03_new_quest_step_01","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q03_new_quest_step_06","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q04_new_quest_start","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q05_new_quest_start","speaker_external_id":"Old Man","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q05_new_quest_step_01","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}},{"key":"verbs_to_be_q05_new_quest_step_07","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\verbs_to_be.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"mayadialougtobe","locale":"he","line_order":0,"content":"אוי לא... אני בצרה!\nשכחתי את חוקי האנגלית של הממלכה - am, is ו-are...","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q01_new_quest_step_01_3","locale":"he","line_order":0,"content":"שלום! אני Cannoneer!\nI am Cannoneer!\nאני המומחה של הפועל הקסום AM.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q02_new_quest_start","locale":"he","line_order":0,"content":"כל הכבוד! \nאני ממש מתרשם! נראה שהבנתם מצוין איך משתמשים ב-AM.\nאבל המסע שלנו עדיין לא הסתיים...","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q02_new_quest_step_01","locale":"he","line_order":0,"content":"שלום לכם! אני Benny the Builder.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q02_new_quest_step_04","locale":"he","line_order":0,"content":"כל הכבוד!\nהצלחתם לפתור את כל האתגרים!\nאבל... יש לנו בעיה קטנה.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q02_new_quest_step_08","locale":"he","line_order":0,"content":"מצאתם את ה-Knight Gauntlet Blueprint! מצוין!\nעכשיו אני סוף סוף יכול להתחיל לבנות את הבסיס.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q03_new_quest_step_01","locale":"he","line_order":0,"content":"שלום, הרפתקנים צעירים.\nBenny the Builder כבר סיפר לי שתגיעו.\nואני יודע בדיוק למה אתם כאן.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q03_new_quest_step_06","locale":"he","line_order":0,"content":"חזרתם!\nואני רואה שגם Whiskers חזר איתכם! \nידעתי שהוא יגיע רק אם תשתמשו נכון ב-AM וב-IS.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q04_new_quest_start","locale":"he","line_order":0,"content":"מצוין! עכשיו תורכם להתאמן על הפועל ARE.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q04_new_quest_start","locale":"he","line_order":1,"content":"לכו ל-Silver Fountain Court ול-Exam Table ב-Fairy Rose Park.\nהשלימו את כל האתגרים בשני המקומות, ואז חזרו אליי.","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q05_new_quest_start","locale":"he","line_order":0,"content":"כל הכבוד!\nהשלמתם את כל האתגרים בהצלחה.\nעכשיו אתם מכירים את כל שלושת הפעלים הקסומים - AM, IS ו-ARE","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q05_new_quest_step_01","locale":"he","line_order":0,"content":"חזרתם!\nאז... הצלחתם ללמוד את כל החוקים?\nאבל אני עדיין לא זוכרת אותם...\n","line_format":"plain_text"},{"dialogue_key":"verbs_to_be_q05_new_quest_step_07","locale":"he","line_order":0,"content":"תודה רבה לכם! \nממש הצלתם אותי.\nכל כך פחדתי שהשומרים יגלו ששכחתי את החוקים...","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
